import json,glob
for f in glob.glob('*.json'):
 try: d=json.load(open(f))
 except: continue
 s=json.dumps(d)
 if 'community/tweets' in s:
 print('FILE:',f)
 def walk(o):
 if isinstance(o,dict):
 if str(o.get('path','')).endswith('community/tweets'): print(json.dumps(o,indent=1)[:1500])
 for v in o.values(): walk(v)
 elif isinstance(o,list):
 for v in o: walk(v)
 walk(d)
"

